declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('clinical.write');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$t=(int)$user['tenant_id'];$selected=(int)($_GET['patient_id']??$_POST['patient_id']??0);$sql="SELECT * FROM patients WHERE tenant_id=:t AND status='active'";$pa=['t'=>$t];if(in_array($user['role_slug'],['psychologist','supervised','clinic_admin'],true)){$sql.=' AND primary_professional_id=:u';$pa['u']=$user['id'];}$sql.=' ORDER BY name';$st=db()->prepare($sql);$st->execute($pa);$patients=$st->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$patientId=(int)($_POST['patient_id']??0);$patient=null;foreach($patients as $x)if((int)$x['id']===$patientId)$patient=$x;if(!$patient||!\App\Core\Rbac::canViewPatientClinical($user,$patient))$error='Paciente não autorizado.';else{$type=$_POST['record_type']??'soap';if(!in_array($type,['soap','narrative'],true))$type='soap';if($type==='soap'){$content=['S'=>trim($_POST['s']??''),'O'=>trim($_POST['o']??''),'A'=>trim($_POST['a']??''),'P'=>trim($_POST['p']??'')];}else{$content=['narrative'=>trim($_POST['narrative']??'')];}if(!array_filter($content,fn($v)=>$v!==''))$error='Inclua conteúdo clínico.';else{$status=$user['role_slug']==='supervised'?'pending_approval':'draft';$supervisor=$user['role_slug']==='supervised'?(int)($user['supervisor_id']??0):null;if($status==='pending_approval'&&(!$supervisor||$supervisor<1))$error='Seu perfil supervisionado não possui supervisor configurado.';else{$enc=\App\Core\Crypto::encrypt($content);$st=db()->prepare("INSERT INTO clinical_records(tenant_id,patient_id,professional_id,supervisor_id,record_type,content_enc,status,created_at,updated_at) VALUES(:t,:p,:u,:sup,:type,:c,:status,NOW(),NOW())");$st->execute(['t'=>$t,'p'=>$patientId,'u'=>$user['id'],'sup'=>$supervisor?:null,'type'=>$type,'c'=>$enc,'status'=>$status]);$id=(int)db()->lastInsertId();audit('clinical.record_create','clinical_record',$id,['patient_id'=>$patientId,'status'=>$status]);flash('success',$status==='pending_approval'?'Registro enviado para aprovação do supervisor.':'Evolução salva como rascunho.');redirect('clinical/view.php?id='.$id);}}}}
layout('Nova evolução',function()use($patients,$selected,$error){?><div class="page-head"><div><span class="eyebrow">Prontuário</span><h1>Nova evolução clínica</h1><p>O conteúdo é cifrado antes de ser persistido no MySQL.</p></div></div><form method="post" class="card form-grid"><?=csrf_field()?><?php if($error):?><div class="error-box"><?=e($error)?></div><?php endif?><div class="form-row"><div class="field"><label>Paciente</label><select name="patient_id" required><option value="">Selecione</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>" <?= $selected===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach?></select></div><div class="field"><label>Formato</label><select name="record_type" id="record-type"><option value="soap">SOAP</option><option value="narrative">Narrativo</option></select></div></div><div id="soap-fields" class="soap-grid"><div class="field soap-box"><label>S · Subjetivo</label><textarea name="s" placeholder="Relatos, queixas e percepções trazidas pelo paciente."></textarea></div><div class="field soap-box"><label>O · Objetivo</label><textarea name="o" placeholder="Observações do profissional."></textarea></div><div class="field soap-box"><label>A · Avaliação</label><textarea name="a" placeholder="Análise clínica cautelosa e hipóteses."></textarea></div><div class="field soap-box"><label>P · Plano</label><textarea name="p" placeholder="Intervenções, tarefas e próximos passos."></textarea></div></div><div id="narrative-fields" class="field" style="display:none"><label>Registro narrativo</label><textarea name="narrative" style="min-height:260px"></textarea></div><div class="help">O sistema não diagnostica nem assina por você. Registros supervisionados seguem automaticamente para aprovação.</div><button class="button">Salvar evolução</button></form><script>document.querySelector('#record-type')?.addEventListener('change',e=>{const n=e.target.value==='narrative';document.querySelector('#soap-fields').style.display=n?'none':'grid';document.querySelector('#narrative-fields').style.display=n?'grid':'none';});</script><?php },['active'=>'clinical']);
